using Ina.Linker.Elf;

namespace Ina.Linker.Output;

/// <summary>A contiguous piece of the output file: either a section built from inputs or one generated by the linker.</summary>
internal abstract class OutputChunk(string name, uint type, ulong flags, ulong alignment)
{
    public string Name { get; } = name;

    public uint Type { get; protected set; } = type;

    public ulong Flags { get; protected set; } = flags;

    public ulong Alignment { get; protected set; } = Math.Max(alignment, 1);

    public ulong Size { get; protected set; }

    /// <summary>Virtual address in the output image. Valid after layout.</summary>
    public ulong Address { get; set; }

    /// <summary>File offset in the output. Valid after layout.</summary>
    public ulong FileOffset { get; set; }

    /// <summary>Index in the section header table of the output, or 0 when the chunk has no section header.</summary>
    public int SectionIndex { get; set; }

    /// <summary>The chunk whose section index goes into <c>sh_link</c>.</summary>
    public OutputChunk? LinkedChunk { get; set; }

    public uint Info { get; set; }

    public ulong EntrySize { get; protected set; }

    public bool IsNoBits => Type == SectionType.NoBits;

    public bool IsAlloc => (Flags & SectionFlags.Alloc) != 0;

    public bool IsWritable => (Flags & SectionFlags.Write) != 0;

    public bool IsExecutable => (Flags & SectionFlags.ExecInstr) != 0;

    public bool IsTls => (Flags & SectionFlags.Tls) != 0;

    /// <summary>Writes the content of the chunk. Not called for NOBITS chunks.</summary>
    public abstract void Write(Span<byte> destination, LinkContext context);

    public override string ToString() => Name;
}
